arguments.command:
cd /tmp/vally-eval-trial-UC7slo; mkdir -p tests/CheckoutPricing.UnitTests/Checkout
cat > src/CheckoutPricing.Application/CheckoutCalculator.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class CheckoutCalculator
{
    public decimal CalculatePayableTotal(string customerTier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerReceivesTheApprovedDiscount()
    {
        var total = new CheckoutCalculator().CalculatePayableTotal("Gold", 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

